//! Component dumps of the imaging widgets: each one's resolved style (its pure `style` function) in
//! every built-in and mode, as text under `tests/dumps/components/`. Rewrite with
//! `UPDATE_DUMPS=1 cargo test -p craft-imaging --features ui --test control_dumps`.

use craft_imaging::ui::{LevelsEditor, WarpGrid};
use craft_theme::{State, States, TypeRole};
use craft_ui::testing::dump::{Dump, check_component};
use craft_ui::theme::UiTokens;
use egui::Color32;

const HEADER: &str =
    "Generated by crates/imaging/tests/control_dumps.rs; rewrite with UPDATE_DUMPS=1 cargo test -p craft-imaging --features ui --test control_dumps";

fn check(file: &str, each: impl FnMut(&mut Dump, &UiTokens)) {
    check_component(format!("{}/tests/dumps/components/{file}", env!("CARGO_MANIFEST_DIR")), HEADER, each);
}

fn states(d: &mut Dump, key: &str, colors: &States<Color32>) {
    for state in State::ALL {
        d.line(&format!("{key}.{}", state.name()), colors.get(state));
    }
}

fn role(role: TypeRole) -> &'static str {
    match role {
        TypeRole::Caption => "caption",
        TypeRole::Label => "label",
        TypeRole::Body => "body",
        TypeRole::BodyStrong => "body_strong",
        TypeRole::Title => "title",
        TypeRole::Heading => "heading",
        TypeRole::BodyLarge => "body_large",
        TypeRole::Overline => "overline",
        TypeRole::Mono => "mono",
    }
}

/// Levels editors: the width range, the rows, thumbs and bar, the thumb edges and ring, the
/// captions and the gap between fields.
#[test]
fn levels_editor() {
    check("levels_editor.txt", |d, t| {
        let s = LevelsEditor::style(t);
        d.line("min_width", s.min_width).line("max_width", s.max_width).line("row", s.row).line("bar", s.bar);
        d.line("thumb_width", s.thumb_width).line("thumb_height", s.thumb_height).line("hit", s.hit);
        d.line("thumb_edge", s.thumb_edge).line("disabled_edge", s.disabled_edge);
        states(d, "ring", &s.ring);
        d.line("ring_width", s.ring_width).line("caption_role", role(s.caption_role)).line("field_gap", s.field_gap);
    });
}

/// Warp grids: the patch boundaries and thirds, the anchor and handle end looks, the arm, the
/// reach and the reveal distance.
#[test]
fn warp() {
    check("warp.txt", |d, t| {
        let s = WarpGrid::style(t);
        d.line("line", s.line).line("minor", s.minor);
        for (key, h) in [("anchor", &s.anchor), ("control", &s.control)] {
            d.line(&format!("{key}.size"), h.size).line(&format!("{key}.fill"), h.fill);
            d.line(&format!("{key}.stroke"), h.stroke).line(&format!("{key}.halo"), h.halo);
        }
        d.line("arm", s.arm).line("hit", s.hit).line("reveal", s.reveal).line("flatten", s.flatten);
    });
}
